1	package govflow
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// delegatedVoteInput 是本文件回归场景共用的提案：甲、乙、丙的原始权重分别为
12	// 300、400、300，乙委托给甲（甲名下归集 700），法定人数 600，投票窗口
13	// [100,200)，时间锁 300。动作只用于创建提案；投票、查询与计票都不执行它。
14	func delegatedVoteInput(id string) *CreateVoteInput {
15		return &CreateVoteInput{
16			ID: id,
17			Members: []VoteMember{
18				{ID: "甲", Weight: 300},
19				{ID: "乙", Weight: 400},
20				{ID: "丙", Weight: 300},
21			},
22			Delegations: []Delegation{{From: "乙", To: "甲"}},
23			Quorum:      600,
24			StartAt:     100,
25			Deadline:    200,
26			TimelockEnd: 300,
27			Actions:     []string{"transfer:audits:100"},
28		}
29	}
30	
31	// assertDelegatedMembers 断言成员视图保持创建时的内容：原始权重、完整委托
32	// 路径、最终代表与直接委托对象都不因投票或保存失败而改变。
33	func assertDelegatedMembers(t *testing.T, prefix string, v *VoteProposalView) {
34		t.Helper()
35		want := map[string]MemberView{
36			"甲": {ID: "甲", Weight: 300, Path: []string{"甲"}, Delegate: "甲", Direct: ""},
37			"乙": {ID: "乙", Weight: 400, Path: []string{"乙", "甲"}, Delegate: "甲", Direct: "甲"},
38			"丙": {ID: "丙", Weight: 300, Path: []string{"丙"}, Delegate: "丙", Direct: ""},
39		}
40		assertMemberViews(t, prefix, memberPaths(v), want)
41	}
42	
43	// assertNoFundsMoved 断言投票、查询与计票都不执行提案动作：资金余额保持
44	// 初始值，没有收款账户，也没有执行凭据。
45	func assertNoFundsMoved(t *testing.T, store *Store, treasury int64) {
46		t.Helper()
47		if bal, err := store.TreasuryBalance(); err != nil || bal != treasury {
48			t.Fatalf("treasury = %d err=%v, want untouched %d", bal, err, treasury)
49		}
50		if all, err := store.Balances(); err != nil || len(all) != 0 {
51			t.Fatalf("recipient balances = %v err=%v, want none", all, err)
52		}
53		if receipts, err := store.Receipts(); err != nil || len(receipts) != 0 {
54			t.Fatalf("receipts = %v err=%v, voting must not produce receipts", receipts, err)
55		}
56	}
57	
58	// assertBingThenJiaBallots 断言查询视图恰好保留两张票：丙在 120 的 300 权重
59	// 反对票在前，甲在 150 的 700 权重赞成票（含乙委托的 400）在后；提案仍在
60	// 投票中，没有提前计票；创建参数与成员委托关系保持原样。
61	func assertBingThenJiaBallots(t *testing.T, store *Store, id string) {
62		t.Helper()
63		v, ok, err := store.VoteProposal(id)
64		if err != nil || !ok {
65			t.Fatalf("VoteProposal: ok=%v err=%v", ok, err)
66		}
67		if v.State != "voting" || v.Tally != nil {
68			t.Fatalf("state=%s tally=%+v, want voting with no tally", v.State, v.Tally)
69		}
70		if len(v.Ballots) != 2 {
71			t.Fatalf("ballots = %+v, want exactly 丙 then 甲", v.Ballots)
72		}
73		if b := v.Ballots[0]; b.Representative != "丙" || b.Weight != 300 || b.Support || b.VotedAt != 120 {
74			t.Fatalf("first ballot = %+v, want 丙 weight=300 against voted_at=120", b)
75		}
76		if b := v.Ballots[1]; b.Representative != "甲" || b.Weight != 700 || !b.Support || b.VotedAt != 150 {
77			t.Fatalf("second ballot = %+v, want 甲 weight=700 for voted_at=150", b)
78		}
79		if v.Quorum != 600 || v.StartAt != 100 || v.Deadline != 200 || v.TimelockEnd != 300 || v.TotalWeight != 1000 {
80			t.Fatalf("proposal parameters changed: %+v", v)
81		}
82		if !sameActions(v.Actions, []string{"transfer:audits:100"}) {
83			t.Fatalf("actions = %v, want original action text", v.Actions)
84		}
85		assertDelegatedMembers(t, "after durability warning", v)
86	}
87	
88	// TestVoteDirSyncFailureKeepsWrittenBallot：最终代表在投票窗口内首次投票时，
89	// 状态文件替换成功、随后目录同步失败——Go 调用必须返回 nil 票据与可按
90	// ErrDurabilityUnconfirmed 识别的错误（保留具体保存原因），而不是普通成功，
91	// 也不能解释成投票资格不符。错误不撤销已写入的票：恢复读取后，丙的反对票与
92	// 甲的 700 权重赞成票都完整登记；同选择重试返回 150 的首次记录，改投按冲突
93	// 拒绝；到期计票为赞成 700、反对 300、参与 1000 的通过结论。
94	func TestVoteDirSyncFailureKeepsWrittenBallot(t *testing.T) {
95		store, path := openTempStore(t, 1000)
96		defer store.Close()
97		const id = "gip-vote-dursync"
98		mustCreateVote(t, store, delegatedVoteInput(id))
99		if _, err := store.CastVote(id, "丙", false, 120); err != nil {
100			t.Fatalf("丙 vote: %v", err)
101		}
102	
103		// 目录可写可进入但不可读：临时文件写入、fsync 与原子改名成功，
104		// 只有随后的目录同步失败。
105		makeDirSyncFail(t, path)
106		ballot, err := store.CastVote(id, "甲", true, 150)
107		if err == nil {
108			t.Fatal("expected durability warning error, got nil")
109		}
110		// 不是普通成功：票据结果为 nil，错误可按 ErrDurabilityUnconfirmed 识别。
111		if ballot != nil {
112			t.Fatalf("durability warning must not return a success ballot: %+v", ballot)
113		}
114		if !errors.Is(err, ErrDurabilityUnconfirmed) {
115			t.Fatalf("err = %v, want errors.Is ErrDurabilityUnconfirmed", err)
116		}
117		var derr *DurabilityError
118		if !errors.As(err, &derr) || derr.Cause == nil {
119			t.Fatalf("err = %v (%T), want *DurabilityError with cause", err, err)
120		}
121		if !strings.Contains(err.Error(), derr.Cause.Error()) {
122			t.Fatalf("err %q must preserve the underlying save failure %q", err, derr.Cause)
123		}
124		// 不能解释成投票资格不符或选择冲突。
125		if errors.Is(err, ErrVoteRejected) {
126			t.Fatalf("a valid first vote must not be rejected as a business rule: %v", err)
127		}
128		if errors.Is(err, ErrProposalConflict) {
129			t.Fatalf("a first vote must not be reported as a conflict: %v", err)
130		}
131	
132		// 恢复正常读取条件：报错时已写入的甲票完整登记——代表、归集权重、
133		// 赞成选择与首次投票时间 150 都来自当次提交；丙的反对票保持原内容
134		// 且排在其前；提案仍在投票中，没有提前计票。
135		if err := os.Chmod(filepath.Dir(path), 0o700); err != nil {
136			t.Fatalf("restore dir: %v", err)
137		}
138		assertBingThenJiaBallots(t, store, id)
139		assertNoFundsMoved(t, store, 1000)
140	
141		// 重新打开后读到完全相同的两张票与投票中状态。
142		if err := store.Close(); err != nil {
143			t.Fatalf("close: %v", err)
144		}
145		reopened, err := Open(path)
146		if err != nil {
147			t.Fatalf("reopen after durability warning: %v", err)
148		}
149		defer reopened.Close()
150		assertBingThenJiaBallots(t, reopened, id)
151	
152		// 甲再次提交相同选择：即使提供的时间已经到达截止时刻，也返回 150 的
153		// 首次记录且不追加票据。
154		retry, err := reopened.CastVote(id, "甲", true, 200)
155		if err != nil {
156			t.Fatalf("same-choice retry at deadline: %v", err)
157		}
158		if retry.Representative != "甲" || retry.Weight != 700 || !retry.Support || retry.VotedAt != 150 {
159			t.Fatalf("same-choice retry = %+v, want first record 甲 for 700 voted_at=150", retry)
160		}
161		// 改投反对按既有冲突规则拒绝，原票保持不变。
162		if _, err := reopened.CastVote(id, "甲", false, 160); !errors.Is(err, ErrProposalConflict) {
163			t.Fatalf("changing vote err=%v, want ErrProposalConflict", err)
164		}
165		assertBingThenJiaBallots(t, reopened, id)
166	
167		// 截止时刻计票：赞成 700、反对 300、参与 1000，达到法定人数且赞成严格
168		// 多于反对 => 通过；报错时已写入的甲票必须计入，乙的权重不得重复累计。
169		res, err := reopened.TallyVote(id, 200)
170		if err != nil {
171			t.Fatalf("tally: %v", err)
172		}
173		if !res.Passed || res.ForWeight != 700 || res.AgainstWeight != 300 ||
174			res.Turnout != 1000 || res.Quorum != 600 || res.TalliedAt != 200 {
175			t.Fatalf("tally = %+v, want passed for=700 against=300 turnout=1000 at 200", res)
176		}
177		// 计票同样不执行提案动作：资金余额与执行凭据保持原样。
178		assertNoFundsMoved(t, reopened, 1000)
179	}
180	
181	// TestVotePreReplaceFailureStillLeavesNoBallot：必要区分——同一提案场景下，
182	// 保存失败发生在状态文件替换之前时，行为与目录同步失败不同：没有新票据、
183	// 不占用首次投票机会，后续首次投票仍受窗口约束（截止时刻的首次票被拒绝），
184	// 到期计票只含丙的反对票，得出参与 300 的拒绝结论。
185	func TestVotePreReplaceFailureStillLeavesNoBallot(t *testing.T) {
186		store, path := openTempStore(t, 1000)
187		defer store.Close()
188		const id = "gip-vote-pre-replace"
189		mustCreateVote(t, store, delegatedVoteInput(id))
190		if _, err := store.CastVote(id, "丙", false, 120); err != nil {
191			t.Fatalf("丙 vote: %v", err)
192		}
193		before, err := os.ReadFile(path)
194		if err != nil {
195			t.Fatal(err)
196		}
197	
198		// 目录不可写：提交在状态文件替换之前失败，甲的首次票没有写入。
199		makeDirUnwritable(t, path)
200		ballot, err := store.CastVote(id, "甲", true, 150)
201		if err == nil {
202			t.Fatal("expected save failure, got nil error")
203		}
204		if ballot != nil {
205			t.Fatalf("pre-replacement failure must not return a ballot: %+v", ballot)
206		}
207		if errors.Is(err, ErrDurabilityUnconfirmed) {
208			t.Fatalf("pre-replacement failure must not be reported as durability warning: %v", err)
209		}
210		if errors.Is(err, ErrVoteRejected) {
211			t.Fatalf("a valid first vote must not be rejected as a business rule: %v", err)
212		}
213		if !strings.Contains(err.Error(), "permission denied") {
214			t.Fatalf("error must carry the concrete save cause, got %v", err)
215		}
216	
217		// 查询仍只有丙的反对票；状态文件字节与失败前完全一致。
218		assertBingOnlyBallot := func(s *Store) {
219			t.Helper()
220			v, ok, err := s.VoteProposal(id)
221			if err != nil || !ok {
222				t.Fatalf("VoteProposal: ok=%v err=%v", ok, err)
223			}
224			if v.State != "voting" || v.Tally != nil {
225				t.Fatalf("state=%s tally=%+v, want voting with no tally", v.State, v.Tally)
226			}
227			if len(v.Ballots) != 1 {
228				t.Fatalf("ballots = %+v, want only 丙's ballot", v.Ballots)
229			}
230			if b := v.Ballots[0]; b.Representative != "丙" || b.Weight != 300 || b.Support || b.VotedAt != 120 {
231				t.Fatalf("ballot = %+v, want 丙 weight=300 against voted_at=120", b)
232			}
233			assertDelegatedMembers(t, "after pre-replacement failure", v)
234		}
235		assertBingOnlyBallot(store)
236		if after, rerr := os.ReadFile(path); rerr != nil || string(after) != string(before) {
237			t.Fatalf("state file changed despite pre-replacement save failure")
238		}
239	
240		// 恢复保存条件后，首次投票仍受窗口约束：截止时刻 200 的首次票按
241		// 窗口边界 [100,200) 拒绝，失败尝试不曾占用这次机会。
242		if err := os.Chmod(filepath.Dir(path), 0o700); err != nil {
243			t.Fatalf("restore dir: %v", err)
244		}
245		if _, err := store.CastVote(id, "甲", true, 200); !errors.Is(err, ErrVoteRejected) {
246			t.Fatalf("first vote at deadline (exclusive) err=%v, want ErrVoteRejected", err)
247		}
248		assertBingOnlyBallot(store)
249	
250		// 到期计票只含丙的反对票：赞成 0、反对 300、参与 300，未达法定人数
251		// => 拒绝；与目录同步失败场景（甲票已写入、参与 1000 通过）形成对照。
252		res, err := store.TallyVote(id, 200)
253		if err != nil {
254			t.Fatalf("tally: %v", err)
255		}
256		if res.Passed || res.ForWeight != 0 || res.AgainstWeight != 300 ||
257			res.Turnout != 300 || res.Quorum != 600 || res.TalliedAt != 200 {
258			t.Fatalf("tally = %+v, want rejected for=0 against=300 turnout=300 at 200", res)
259		}
260		assertNoFundsMoved(t, store, 1000)
261	}
